/* 统一状态容器（03 §2.2 client-shell）：所有视图只读这里，禁止各自持有业务状态。 */

var STORAGE_KEY = 'dsh-reading-lab.ui'
var STATE_VERSION = 1

function safeStorage() {
  try {
    if (typeof window !== 'undefined' && window.localStorage) return window.localStorage
  } catch (error) {
    /* 隐私模式下访问会抛 */
  }
  return null
}

function readPersistedUi() {
  var storage = safeStorage()
  if (!storage) return {}
  try {
    var raw = storage.getItem(STORAGE_KEY)
    if (!raw) return {}
    var parsed = JSON.parse(raw)
    if (!parsed || parsed.version !== STATE_VERSION) return {}
    return {
      selectedBookId: typeof parsed.selectedBookId === 'string' ? parsed.selectedBookId : null,
      uiMode: parsed.uiMode === 'overlay' ? 'overlay' : 'panel',
    }
  } catch (error) {
    return {}
  }
}

function persistUi(state) {
  var storage = safeStorage()
  if (!storage) return
  try {
    storage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        version: STATE_VERSION,
        selectedBookId: state.selectedBookId,
        uiMode: state.uiMode,
      }),
    )
  } catch (error) {
    /* 配额满/隐私模式：不阻断 UI */
  }
}

function createStore(initial) {
  var current = initial
  var listeners = new Set()
  return {
    get: function () {
      return current
    },
    set: function (patch) {
      var next = typeof patch === 'function' ? patch(current) : patch
      if (!next) return current
      current = Object.assign({}, current, next)
      listeners.forEach(function (listener) {
        try {
          listener(current)
        } catch (error) {
          console.warn('[reading-lab] store listener failed', error)
        }
      })
      return current
    },
    subscribe: function (listener) {
      if (typeof listener !== 'function') return function () {}
      listeners.add(listener)
      return function () {
        listeners.delete(listener)
      }
    },
  }
}

var persisted = readPersistedUi()

var store = createStore({
  // booting → idle（连上 Host）→ 其余由各里程碑填充
  status: 'booting',
  // ok | unavailable（/health 的 storage 字段）
  storage: 'ok',
  pluginVersion: '',
  dshVersion: '',
  books: [],
  revision: 0,
  filter: '',
  selectedBookId: persisted.selectedBookId || null,
  selectedNodeId: null,
  uiMode: persisted.uiMode || 'panel',
  detailOpen: false,
  askOpen: false,
  // 研究笔记只读面板（v0.2）：与详情互不排斥，都覆盖在画布上
  notesOpen: false,
  // 上传进行中：按钮转 loading，避免重复点击
  importing: false,
  lastError: null,
})

/** 视图订阅入口：返回快照，状态变化自动重渲染。 */
function useStore() {
  var snapshotState = React.useState(store.get())
  var snapshot = snapshotState[0]
  var setSnapshot = snapshotState[1]
  React.useEffect(function () {
    return store.subscribe(function (next) {
      setSnapshot(next)
    })
  }, [])
  return snapshot
}

function selectBook(bookId) {
  store.set(function (state) {
    return {
      selectedBookId: bookId,
      selectedNodeId: null,
      detailOpen: false,
    }
  })
  persistUi(store.get())
}

function setUiMode(mode) {
  store.set({ uiMode: mode === 'overlay' ? 'overlay' : 'panel' })
  persistUi(store.get())
}

function setFilter(value) {
  store.set({ filter: typeof value === 'string' ? value : '' })
}

function visibleBooks(state) {
  var query = (state.filter || '').trim().toLowerCase()
  var books = Array.isArray(state.books) ? state.books : []
  if (!query) return books
  return books.filter(function (book) {
    var haystack = String(book.title || '') + ' ' + String(book.author || '')
    return haystack.toLowerCase().indexOf(query) !== -1
  })
}

// ---- src/client/api.js ----
/* Host API 客户端（03 §2.3：views 禁止直接 fetch，只经由这里）。 */

function ApiError(code, message, details, status) {
  var error = new Error(message || code)
  error.name = 'ApiError'
  error.code = code || 'E_UNKNOWN'
  error.details = details
  error.status = status || 0
  return error
}

function readJsonSafe(response) {
  return response
    .json()
    .catch(function () {
      return null
    })
}

function envelopeData(body, response) {
  if (body && body.ok === true) return body.data
  var wire = body && body.error ? body.error : null
  var code = wire && typeof wire.code === 'string' ? wire.code : response.status === 401 ? 'E_BAD_REQUEST' : 'E_UNKNOWN'
  var message = wire && typeof wire.message === 'string' ? wire.message : t('error.' + code)
  throw ApiError(code, message, wire ? wire.details : undefined, response.status)
}

async function request(path, options) {
  var init = Object.assign(
    {
      method: 'GET',
      headers: { Accept: 'application/json' },
      credentials: 'same-origin',
    },
    options || {},
  )
  var response
  try {
    response = await fetch(API_BASE + path, init)
  } catch (cause) {
    throw ApiError('E_UNKNOWN', t('state.unavailable'), undefined, 0)
  }
  var body = await readJsonSafe(response)
  return envelopeData(body, response)
}

var api = {
  /** /health 在存储不可用时返回 503，但 body 里仍带 data，所以要单独处理。 */
  health: async function () {
    var response = await fetch(API_BASE + '/health', {
      method: 'GET',
      headers: { Accept: 'application/json' },
      credentials: 'same-origin',
    })
    var body = await readJsonSafe(response)
    if (body && body.data) return body.data
    if (body && body.error) {
      throw ApiError(body.error.code, body.error.message, body.error.details, response.status)
    }
    throw ApiError('E_UNKNOWN', t('state.unavailable'), undefined, response.status)
  },

  listBooks: function () {
    return request('/books')
  },

  /**
   * GUI 上传（04 §4.3）：raw body + `?name=`，不解析 multipart。
   * 返回 `{ duplicate, book }`；导入失败由 Host 给出可读错误码。
   * @param {{ name?: string, type?: string }} file
   */
  importBook: function (file) {
    var name = file && typeof file.name === 'string' ? file.name : 'upload.epub'
    return request('/books/import?name=' + encodeURIComponent(name), {
      method: 'POST',
      headers: { Accept: 'application/json', 'Content-Type': 'application/octet-stream' },
      body: file,
    })
  },

  /**
   * 研究笔记（只读）：无笔记时后端返回 `{updatedAt:null,sections:[]}`，不是 404。
   * @param {string} bookId
   */
  getNotes: function (bookId) {
    return request('/books/' + encodeURIComponent(bookId) + '/notes')
  },

  /**
   * SSE：首帧 hello 带全量书库，之后按事件类型回调。
   * @param {{ onHello?: Function, onEvent?: Function, onError?: Function }} handlers
   * @returns {() => void} 关闭
   */
  subscribeEvents: function (handlers) {
    if (typeof EventSource !== 'function') return function () {}
    var source
    try {
      source = new EventSource(API_BASE + '/events', { withCredentials: true })
    } catch (error) {
      return function () {}
    }
    function close() {
      try {
        source.close()
      } catch (error) {
        /* already closed */
      }
    }
    var types = ['hello', 'book', 'progress', 'map', 'notes', 'thread', 'export']
    types.forEach(function (type) {
      source.addEventListener(type, function (event) {
        var payload = null
        try {
          payload = JSON.parse(event.data)
        } catch (error) {
          payload = null
        }
        try {
          if (type === 'hello' && handlers && handlers.onHello) handlers.onHello(payload)
          else if (handlers && handlers.onEvent) handlers.onEvent(type, payload)
        } catch (error) {
          console.warn('[reading-lab] event handler failed', error)
        }
      })
    })
    source.onerror = function () {
      try {
        if (handlers && handlers.onError) handlers.onError()
      } catch (error) {
        /* ignore */
      }
    }
    return close
  },
}

// ---- src/client/views/header.js ----
/* 顶部工具条（owner: library，03 §4.1 header 48px）。 */

VIEWS.Header = function Header(props) {
  var state = props.state
  var actions = props.actions
  var count = Array.isArray(state.books) ? state.books.length : 0
  var children = [
    h('span', { key: 'title', className: 'rl-header__title' }, t('panel.title')),
    h('span', { key: 'subtitle', className: 'rl-header__subtitle' }, t('panel.subtitle')),
    h('span', { key: 'spacer', className: 'rl-header__spacer' }),
  ]

  if (state.storage === 'unavailable') {
    children.push(
      h('span', { key: 'warn', className: 'rl-header__warn', role: 'status' }, t('header.storage.unavailable')),
    )
  }
  if (state.lastError) {
    children.push(
      h('span', { key: 'error', className: 'rl-header__error', role: 'alert' }, t('error.' + state.lastError)),
    )
  }
  children.push(h('span', { key: 'count', className: 'rl-header__count' }, t('header.count', { count: count })))
  children.push(
    h(
      'button',
      {
        key: 'ask',
        type: 'button',
        className: 'rl-btn' + (state.askOpen ? ' rl-btn--primary' : ''),
        'aria-pressed': state.askOpen ? 'true' : 'false',
        onClick: actions.toggleAsk,
      },
      t('ask.title'),
    ),
  )
  children.push(
    h(
      'button',
      {
        key: 'refresh',
        type: 'button',
        className: 'rl-btn rl-btn--ghost',
        onClick: actions.refresh,
        'aria-label': t('header.refresh'),
      },
      t('header.refresh'),
    ),
  )
  children.push(
    h(
      'button',
      {
        key: 'import',
        type: 'button',
        className: 'rl-btn rl-btn--primary',
        onClick: actions.importBook,
        disabled: Boolean(state.importing),
      },
      state.importing ? t('library.status.parsing') : t('header.import'),
    ),
  )
  return h('header', { className: 'rl-header' }, children)
}

// ---- src/client/views/library.js ----
/* 书架（owner: library，03 §4.1 宽 280 / 240–360）。 */

function bookStatusLabel(status) {
  if (status === 'parsing') return t('library.status.parsing')
  if (status === 'ready') return t('library.status.ready')
  if (status === 'failed') return t('library.status.failed')
  if (status === 'unsupported') return t('library.status.unsupported')
  return ''
}

function BookCard(props) {
  var book = props.book
  var selected = props.selected
  var meta = []
  var label = bookStatusLabel(book.status)
  if (label) meta.push(h('span', { key: 'status', className: 'rl-pill rl-pill--' + (book.status || '') }, label))
  if (book.stats && typeof book.stats.chapters === 'number') {
    meta.push(h('span', { key: 'chapters' }, t('library.meta.chapters', { count: book.stats.chapters })))
  }
  return h(
    'button',
    {
      type: 'button',
      className: 'rl-card',
      role: 'option',
      'aria-selected': selected ? 'true' : 'false',
      onClick: function () {
        props.onSelect(book.id)
      },
    },
    h('span', { className: 'rl-card__title', title: book.title || '' }, book.title || book.id),
    h('span', { className: 'rl-card__meta' }, meta),
  )
}

VIEWS.Library = function Library(props) {
  var state = props.state
  var actions = props.actions
  var books = visibleBooks(state)
  var body

  if (books.length > 0) {
    body = h(
      'ul',
      { className: 'rl-library__list', role: 'listbox', 'aria-label': t('library.title') },
      books.map(function (book) {
        return h(
          'li',
          { key: book.id, role: 'none' },
          h(BookCard, {
            book: book,
            selected: state.selectedBookId === book.id,
            onSelect: actions.selectBook,
          }),
        )
      }),
    )
  } else if (state.filter) {
    body = h('div', { className: 'rl-status' }, t('library.empty.title'))
  } else {
    body = h(
      'div',
      { className: 'rl-empty' },
      h(
        'svg',
        { className: 'rl-empty__icon', viewBox: '0 0 48 48', 'aria-hidden': 'true', focusable: 'false' },
        h('path', {
          fill: 'currentColor',
          d: 'M8 10h13c2 0 3 1 3 3v25c0-2-1-3-3-3H8V10zm32 0H27c-2 0-3 1-3 3v25c0-2 1-3 3-3h13V10z',
        }),
      ),
      h('div', { className: 'rl-empty__title' }, t('library.empty.title')),
      h('div', { className: 'rl-empty__hint' }, t('library.empty.hint')),
      h(
        'div',
        { className: 'rl-empty__actions' },
        h(
          'button',
          { type: 'button', className: 'rl-btn rl-btn--primary', onClick: actions.importBook },
          t('library.empty.action'),
        ),
      ),
    )
  }

  return h(
    'aside',
    { className: 'rl-library', 'aria-label': t('library.title') },
    h(
      'div',
      { className: 'rl-library__head' },
      h('span', { className: 'rl-library__title' }, t('library.title')),
      // 笔记只读面板的入口：选中一本书后才可用（v0.2 由 Agent 生成）。
      h(
        'button',
        {
          type: 'button',
          className: 'rl-btn rl-btn--ghost',
          onClick: actions.toggleNotes,
          disabled: !state.selectedBookId,
          title: t('notes.toggle'),
        },
        t('notes.toggle'),
      ),
      h(
        'button',
        {
          type: 'button',
          className: 'rl-btn rl-btn--ghost',
          onClick: actions.importBook,
          disabled: Boolean(state.importing),
          title: t('library.empty.action'),
        },
        state.importing ? t('library.status.parsing') : t('library.empty.action'),
      ),
      // 真正的文件选择器：按钮只负责 click()，见 overlay.js 的 importBook。
      h('input', {
        id: 'rl-file-input',
        className: 'rl-file-input',
        type: 'file',
        accept: '.epub,.pdf',
        'aria-label': t('library.empty.action'),
        onChange: actions.pickFile,
      }),
    ),
    h(
      'div',
      { style: { padding: '0 12px 8px' } },
      h('input', {
        className: 'rl-input',
        type: 'search',
        value: state.filter,
        placeholder: t('library.search.placeholder'),
        'aria-label': t('library.search.placeholder'),
        onChange: function (event) {
          setFilter(event && event.target ? event.target.value : '')
        },
      }),
    ),
    body,
  )
}

// ---- src/client/svg.js ----
/* SVG 导图几何与场景构建（owner: canvas，03 §2.2 / §7.4）。
 *
 * 这一层只做纯计算：坐标来自 map.json 的 layout（Host 计算，Client 不得重算），
 * 这里只负责「哪些节点可见、连线怎么画、文字怎么折行、视口怎么裁剪」。
 * 不读 DOM、不读 store，便于在 node:test 里直接跑 500 节点样例。
 */

var SVG = (function () {
  var MIN_ZOOM = 0.25
  var MAX_ZOOM = 2
  var FIT_MIN_ZOOM = 0.02
  var FIT_PADDING = 48
  var CARD_PADDING = 12
  var TITLE_LINE = 20
  var SUMMARY_LINE = 18
  var DEPTH_TOKENS = [
    'var(--dsw-alias-brand-primary)',
    'var(--dsw-alias-state-business-primary)',
    'var(--dsw-alias-state-success-primary)',
    'var(--dsw-alias-state-warn-primary)',
  ]

  function clamp(value, min, max) {
    if (!isFinite(value)) return min
    if (value < min) return min
    if (value > max) return max
    return value
  }

  function isCjk(code) {
    return (
      (code >= 0x2e80 && code <= 0x9fff) ||
      (code >= 0xf900 && code <= 0xfaff) ||
      (code >= 0xff00 && code <= 0xffef) ||
      (code >= 0x3000 && code <= 0x303f)
    )
  }

  /** 粗测文本宽度：只用于折行与截断，不追求字体度量级精确。 */
  function measure(text, fontSize, weight) {
    var factor = weight === 600 ? 1.04 : 1
    var total = 0
    for (var index = 0; index < text.length; index += 1) {
      var code = text.codePointAt(index)
      var char = String.fromCodePoint(code)
      if (code > 0xffff) index += 1
      if (isCjk(code)) total += fontSize
      else if (char === ' ') total += fontSize * 0.3
      else if (/[A-Z0-9]/.test(char)) total += fontSize * 0.62
      else total += fontSize * 0.54
    }
    return total * factor
  }

  /** 按词/CJK 字符切分，折行时英文单词不腰斩。 */
  function tokenize(text) {
    var tokens = []
    var buffer = ''
    var index = 0
    while (index < text.length) {
      var code = text.codePointAt(index)
      var char = String.fromCodePoint(code)
      index += char.length
      if (isCjk(code)) {
        if (buffer) {
          tokens.push(buffer)
          buffer = ''
        }
        tokens.push(char)
      } else if (char === ' ' || char === '\t' || char === '\n') {
        if (buffer) {
          tokens.push(buffer)
          buffer = ''
        }
        tokens.push(' ')
      } else {
        buffer += char
      }
    }
    if (buffer) tokens.push(buffer)
    return tokens
  }

  function truncate(text, maxWidth, fontSize, weight) {
    var source = String(text == null ? '' : text).replace(/\s+/g, ' ').trim()
    if (!source) return ''
    if (measure(source, fontSize, weight) <= maxWidth) return source
    var output = ''
    for (var index = 0; index < source.length; index += 1) {
      var next = output + source.charAt(index)
      if (measure(next + '…', fontSize, weight) > maxWidth) break
      output = next
    }
    return output ? output + '…' : '…'
  }

  /** 折行：返回 { lines, truncated }，行数不超过 maxLines。 */
  function wrapText(text, maxWidth, fontSize, maxLines, weight) {
    var source = String(text == null ? '' : text).replace(/\s+/g, ' ').trim()
    if (!source || maxWidth <= 0 || maxLines <= 0) return { lines: [], truncated: false }
    var tokens = tokenize(source)
    var lines = []
    var current = ''
    var truncated = false
    for (var index = 0; index < tokens.length; index += 1) {
      var token = tokens[index]
      var candidate = current ? current + token : token
      if (measure(candidate.replace(/\s+$/, ''), fontSize, weight) <= maxWidth) {
        current = candidate
        continue
      }
      if (current) {
        lines.push(current.replace(/\s+$/, ''))
        current = ''
        if (lines.length >= maxLines) {
          truncated = true
          break
        }
      }
      if (token === ' ') continue
      // 单个 token 超宽。已是最后一行且前面已有内容时，宁可留白加省略号，也不把英文单词拦腰截断。
      if (lines.length + 1 >= maxLines) {
        if (!lines.length) {
          var head = ''
          for (var cursor = 0; cursor < token.length; cursor += 1) {
            var piece = head + token.charAt(cursor)
            if (measure(piece, fontSize, weight) > maxWidth) break
            head = piece
          }
          lines.push((head || token.charAt(0)) + '…')
        }
        truncated = true
        break
      }
      // 单个 token 超宽：按字符硬切。
      var rest = token
      while (rest && measure(rest, fontSize, weight) > maxWidth) {
        var cut = ''
        for (var cursor = 0; cursor < rest.length; cursor += 1) {
          var next = cut + rest.charAt(cursor)
          if (measure(next, fontSize, weight) > maxWidth) break
          cut = next
        }
        if (!cut) cut = rest.charAt(0)
        lines.push(cut)
        rest = rest.slice(cut.length)
        if (lines.length >= maxLines) {
          truncated = Boolean(rest)
          break
        }
      }
      if (lines.length >= maxLines) break
      current = rest
    }
    if (!truncated && current) {
      if (lines.length < maxLines) lines.push(current.replace(/\s+$/, ''))
      else truncated = true
    }
    truncated = truncated || measure(lines.join(''), fontSize, weight) < measure(source, fontSize, weight)
    if (truncated && lines.length) {
      var lastIndex = lines.length - 1
      if (!/…$/.test(lines[lastIndex])) lines[lastIndex] += '…'
    }
    return { lines: lines, truncated: truncated }
  }

  function boundsOf(nodes) {
    var box = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity }
    for (var index = 0; index < nodes.length; index += 1) {
      var node = nodes[index]
      if (node.x < box.minX) box.minX = node.x
      if (node.y < box.minY) box.minY = node.y
      if (node.x + node.w > box.maxX) box.maxX = node.x + node.w
      if (node.y + node.h > box.maxY) box.maxY = node.y + node.h
    }
    if (!isFinite(box.minX)) return { x: 0, y: 0, width: 0, height: 0 }
    return { x: box.minX, y: box.minY, width: box.maxX - box.minX, height: box.maxY - box.minY }
  }

  /** 以 (px,py) 屏幕点为锚缩放；返回新的 {x,y,zoom}。 */
  function zoomAt(view, factor, px, py) {
    // 适应窗口可能低于 25%（500 节点）；此时允许继续缩小到当前比例，但不再放大到 25% 以上跳变。
    var lower = Math.min(view.zoom || 1, MIN_ZOOM)
    var zoom = clamp((view.zoom || 1) * factor, lower, MAX_ZOOM)
    var ratio = zoom / (view.zoom || 1)
    return {
      x: px - (px - view.x) * ratio,
      y: py - (py - view.y) * ratio,
      zoom: zoom,
    }
  }

  /** 屏幕点到世界点。 */
  function toWorld(view, px, py) {
    return { x: (px - view.x) / (view.zoom || 1), y: (py - view.y) / (view.zoom || 1) }
  }

  /** 让 bounds 居中并完整落在 viewport 内；大图允许低于 25%（03 §4.8 500 节点验收）。 */
  function fitView(bounds, viewport, padding) {
    var width = Math.max(1, bounds.width || 0)
    var height = Math.max(1, bounds.height || 0)
    var viewWidth = Math.max(1, (viewport && viewport.width) || 0)
    var viewHeight = Math.max(1, (viewport && viewport.height) || 0)
    var pad = typeof padding === 'number' ? padding : FIT_PADDING
    var zoom = clamp(Math.min((viewWidth - pad * 2) / width, (viewHeight - pad * 2) / height), FIT_MIN_ZOOM, 1)
    return {
      x: (viewWidth - width * zoom) / 2 - bounds.x * zoom,
      y: (viewHeight - height * zoom) / 2 - bounds.y * zoom,
      zoom: zoom,
    }
  }

  function centerOn(node, viewport, zoom) {
    var level = clamp(zoom || 1, FIT_MIN_ZOOM, MAX_ZOOM)
    var viewWidth = Math.max(1, (viewport && viewport.width) || 0)
    var viewHeight = Math.max(1, (viewport && viewport.height) || 0)
    return {
      x: viewWidth / 2 - (node.x + node.w / 2) * level,
      y: viewHeight / 2 - (node.y + node.h / 2) * level,
      zoom: level,
    }
  }

  /** map.json 的 layout 是根节点树 + 扁平 nodes；这里建索引，父关系只认树。 */
  function indexMap(doc) {
    var nodes = {}
    var order = []
    var duplicates = []
    var parentOf = {}
    var childrenOf = {}
    var layout = doc && doc.layout && doc.layout.nodes ? doc.layout.nodes : {}
    function walk(raw, parentId, depth) {
      if (!raw || typeof raw !== 'object' || typeof raw.id !== 'string') return
      if (Object.prototype.hasOwnProperty.call(nodes, raw.id)) {
        // 重复 id 会形成环；记下来让 validateMap 拒绝，而不是无限递归。
        duplicates.push(raw.id)
        return
      }
      var slot = layout[raw.id]
      nodes[raw.id] = raw
      order.push(raw.id)
      parentOf[raw.id] = parentId
      childrenOf[raw.id] = []
      if (parentId) childrenOf[parentId].push(raw.id)
      if (slot && typeof slot.depth === 'number') depth = slot.depth
      var children = Array.isArray(raw.children) ? raw.children : []
      for (var index = 0; index < children.length; index += 1) walk(children[index], raw.id, depth + 1)
    }
    if (doc && doc.root) walk(doc.root, null, 0)
    return { doc: doc, nodes: nodes, order: order, duplicates: duplicates, parentOf: parentOf, childrenOf: childrenOf, layout: layout }
  }

  function validateMap(doc) {
    if (!doc || typeof doc !== 'object') return { ok: false, reason: 'empty' }
    if (doc.schemaVersion !== 1) return { ok: false, reason: 'schema' }
    if (!doc.root || typeof doc.root.id !== 'string') return { ok: false, reason: 'root' }
    if (!doc.layout || typeof doc.layout !== 'object') return { ok: false, reason: 'layout' }
    if (!doc.layout.nodes || typeof doc.layout.nodes !== 'object') return { ok: false, reason: 'layout-nodes' }
    var index = indexMap(doc)
    if (index.duplicates.length) return { ok: false, reason: 'duplicate-id', nodeId: index.duplicates[0] }
    for (var cursor = 0; cursor < index.order.length; cursor += 1) {
      var id = index.order[cursor]
      var slot = index.layout[id]
      if (!slot) return { ok: false, reason: 'missing-layout', nodeId: id }
      if (![slot.x, slot.y, slot.w, slot.h].every(function (value) {
        return typeof value === 'number' && isFinite(value)
      })) {
        return { ok: false, reason: 'bad-geometry', nodeId: id }
      }
    }
    return { ok: true, index: index }
  }

  function citationCount(node) {
    if (!node || !Array.isArray(node.citations)) return 0
    var seen = {}
    var total = 0
    for (var index = 0; index < node.citations.length; index += 1) {
      var citation = node.citations[index]
      var id = citation && (citation.chunkId || citation.id)
      if (!id || seen[id]) continue
      seen[id] = true
      total += 1
    }
    return total
  }

  function summaryLinesFor(node, width, height) {
    if (!node.summary) return { lines: [], truncated: false }
    var available = width - CARD_PADDING * 2
    var maxLines = Math.floor((height - CARD_PADDING * 2 - TITLE_LINE) / SUMMARY_LINE)
    maxLines = clamp(maxLines, 1, 3)
    return wrapText(node.summary, available, 12, maxLines)
  }

  function edgePath(parent, child) {
    var fromRight = child.x >= parent.x + parent.w / 2
    var startX = fromRight ? parent.x + parent.w : parent.x
    var endX = fromRight ? child.x : child.x + child.w
    var startY = parent.y + parent.h / 2
    var endY = child.y + child.h / 2
    var distance = Math.abs(endX - startX)
    var handle = clamp(distance * 0.45, 24, 140)
    var c1 = fromRight ? startX + handle : startX - handle
    var c2 = fromRight ? endX - handle : endX + handle
    return 'M ' + startX + ' ' + startY + ' C ' + c1 + ' ' + startY + ', ' + c2 + ' ' + endY + ', ' + endX + ' ' + endY
  }

  /**
   * 构建可渲染场景。
   * options: { collapsed: {id:true}, selectedId, culling: { view, viewport, margin } }
   */
  function buildScene(doc, options) {
    var settings = options || {}
    var index = indexMap(doc)
    var collapsed = settings.collapsed || {}
    var selectedId = settings.selectedId || null
    var layout = index.layout
    var all = []
    var rendered = []
    var edges = []
    var parentVisible = {}
    var missing = 0

    // 先按树序展开（收起节点的子树整体跳过），再统一做视口裁剪。
    function walk(id, parentId, depth) {
      var raw = index.nodes[id]
      var slot = layout[id]
      if (!raw || !slot) {
        missing += 1
        return
      }
      var children = index.childrenOf[id] || []
      var expanded = children.length > 0 && !collapsed[id]
      var isRoot = depth === 0
      var width = slot.w
      var height = slot.h
      var title = isRoot ? raw.title || settings.bookTitle || '' : raw.title || ''
      var model = {
        id: id,
        kind: raw.kind || (isRoot ? 'book' : 'point'),
        depth: typeof slot.depth === 'number' ? slot.depth : depth,
        side: slot.side || (isRoot ? 'root' : ''),
        parentId: parentId,
        x: slot.x,
        y: slot.y,
        w: width,
        h: height,
        isRoot: isRoot,
        title: title,
        titleText: '',
        author: isRoot ? settings.author || '' : '',
        coverChar: isRoot ? String(title).trim().charAt(0) || '书' : '',
        summaryLines: [],
        summaryTruncated: false,
        citationCount: citationCount(raw),
        questions: Array.isArray(raw.questions) ? raw.questions.length : 0,
        hasChildren: children.length > 0,
        expanded: expanded,
        selected: selectedId === id,
        childCount: children.length,
      }
      if (isRoot) {
        var coverWidth = 40
        var textLeft = CARD_PADDING * 2 + coverWidth + 12
        model.titleText = truncate(title, width - textLeft - CARD_PADDING, 16, 600)
        model.authorText = truncate(model.author, width - textLeft - CARD_PADDING, 12, 400)
        var rootLines = wrapText(raw.summary, width - CARD_PADDING * 2, 12, 2)
        model.summaryLines = rootLines.lines
        model.summaryTruncated = rootLines.truncated
      } else {
        model.titleText = truncate(title, width - CARD_PADDING * 2, 14, 600)
        var summary = summaryLinesFor(raw, width, height)
        model.summaryLines = summary.lines
        model.summaryTruncated = summary.truncated
      }
      all.push(model)
      var visible = true
      if (settings.culling) {
        var view = settings.culling.view || { x: 0, y: 0, zoom: 1 }
        var viewport = settings.culling.viewport || { width: 1200, height: 800 }
        var margin = typeof settings.culling.margin === 'number' ? settings.culling.margin : 240
        var left = model.x * view.zoom + view.x
        var top = model.y * view.zoom + view.y
        var right = (model.x + model.w) * view.zoom + view.x
        var bottom = (model.y + model.h) * view.zoom + view.y
        visible =
          right >= -margin && left <= viewport.width + margin && bottom >= -margin && top <= viewport.height + margin
      }
      if (visible) {
        rendered.push(model)
        parentVisible[id] = true
        if (parentId && parentVisible[parentId]) {
          var parentModel = null
          for (var cursor = 0; cursor < rendered.length; cursor += 1) {
            if (rendered[cursor].id === parentId) parentModel = rendered[cursor]
          }
          if (parentModel) edges.push({ from: parentId, to: id, d: edgePath(parentModel, model), side: model.side })
        }
      }
      if (!expanded) return
      for (var indexChild = 0; indexChild < children.length; indexChild += 1) {
        walk(children[indexChild], id, depth + 1)
      }
    }

    if (doc && doc.root) walk(doc.root.id, null, 0)

    var source = all.length ? all : rendered
    var bounds = boundsOf(source)
    var collapsedCount = 0
    Object.keys(collapsed).forEach(function (id) {
      if (index.nodes[id]) collapsedCount += 1
    })
    if (
      collapsedCount === 0 &&
      doc &&
      doc.layout &&
      typeof doc.layout.width === 'number' &&
      doc.layout.width > 0 &&
      typeof doc.layout.height === 'number' &&
      doc.layout.height > 0
    ) {
      bounds = { x: 0, y: 0, width: doc.layout.width, height: doc.layout.height }
    }
    var stats = (doc && doc.stats) || {}
    return {
      nodes: rendered,
      edges: edges,
      all: all,
      bounds: bounds,
      nodeCount: all.length,
      renderedCount: rendered.length,
      stats: {
        nodes: typeof stats.nodes === 'number' ? stats.nodes : index.order.length,
        depth: typeof stats.depth === 'number' ? stats.depth : 0,
        citations: typeof stats.citations === 'number' ? stats.citations : 0,
      },
      missingLayout: missing,
    }
  }

  /** 大图按需渲染：只保留视口（含一屏余量）内的节点与其两端都可见的连线。 */
  function cullScene(scene, view, viewport, margin) {
    if (!scene || !view || scene.nodes.length <= 300) return scene
    var pad = typeof margin === 'number' ? margin : 240
    var nodes = []
    var kept = {}
    for (var index = 0; index < scene.nodes.length; index += 1) {
      var node = scene.nodes[index]
      var left = node.x * view.zoom + view.x
      var top = node.y * view.zoom + view.y
      var right = (node.x + node.w) * view.zoom + view.x
      var bottom = (node.y + node.h) * view.zoom + view.y
      if (right < -pad || left > viewport.width + pad || bottom < -pad || top > viewport.height + pad) continue
      nodes.push(node)
      kept[node.id] = true
    }
    var edges = []
    for (var cursor = 0; cursor < scene.edges.length; cursor += 1) {
      var edge = scene.edges[cursor]
      if (kept[edge.from] && kept[edge.to]) edges.push(edge)
    }
    return {
      nodes: nodes,
      edges: edges,
      all: scene.all,
      bounds: scene.bounds,
      nodeCount: scene.nodeCount,
      renderedCount: nodes.length,
      stats: scene.stats,
      culled: scene.renderedCount !== nodes.length,
    }
  }

  function navigate(scene, currentId, key) {
    // 大图裁剪后 scene.nodes 只是视口子集；键盘导航要覆盖整棵树。
    var order = scene.all && scene.all.length ? scene.all : scene.nodes
    if (!order.length) return null
    var cursor = -1
    for (var index = 0; index < order.length; index += 1) {
      if (order[index].id === currentId) {
        cursor = index
        break
      }
    }
    if (key === 'next') return order[cursor < 0 ? 0 : Math.min(order.length - 1, cursor + 1)].id
    if (key === 'previous') return order[cursor < 0 ? 0 : Math.max(0, cursor - 1)].id
    if (cursor < 0) return order[0].id
    var node = order[cursor]
    if (key === 'first') return order[0].id
    if (key === 'last') return order[order.length - 1].id
    if (key === 'child') {
      for (var next = cursor + 1; next < order.length; next += 1) {
        if (order[next].parentId === node.id) return order[next].id
      }
      return node.id
    }
    if (key === 'parent') {
      if (!node.parentId) return node.id
      for (var back = cursor - 1; back >= 0; back -= 1) {
        if (order[back].id === node.parentId) return order[back].id
      }
      return node.parentId
    }
    return node.id
  }

  function ancestorsOf(index, nodeId) {
    var output = []
    var current = index.parentOf[nodeId]
    while (current) {
      output.push(current)
      current = index.parentOf[current]
    }
    return output
  }

  return {
    MIN_ZOOM: MIN_ZOOM,
    MAX_ZOOM: MAX_ZOOM,
    FIT_MIN_ZOOM: FIT_MIN_ZOOM,
    DEPTH_TOKENS: DEPTH_TOKENS,
    clamp: clamp,
    measure: measure,
    truncate: truncate,
    wrapText: wrapText,
    boundsOf: boundsOf,
    zoomAt: zoomAt,
    toWorld: toWorld,
    fitView: fitView,
    centerOn: centerOn,
    indexMap: indexMap,
    validateMap: validateMap,
    citationCount: citationCount,
    buildScene: buildScene,
    cullScene: cullScene,
    navigate: navigate,
    ancestorsOf: ancestorsOf,
    edgePath: edgePath,
  }
})()

